def transform(grid):
    h = len(grid)
    mr, mc = next((r, c - 8) for r, row in enumerate(grid)
                  for c, v in enumerate(row) if v == 5)
    out = [[0] * 7 for _ in range(h)]
    out[mr][mc] = 5

    # The motifs are read down the left column of tiles, then down the right.
    pieces = []
    for x in (0, 4):
        for y in range(0, h - 2, 4):
            color = next((grid[y + dy][x + dx]
                          for dy in range(3) for dx in range(3)
                          if grid[y + dy][x + dx] != 0), 0)
            if color:
                pieces.append(color)

    r, c = mr + 1, mc
    for color in pieces:
        if color == 6:
            for rr in range(r, min(h, r + 2)):
                if 0 <= c < 7:
                    out[rr][c] = 6
            r += 2
        else:
            length = {1: 3, 2: 2, 3: 4}[color]
            start = c if color == 1 else c - length + 1
            for cc in range(start, start + length):
                if 0 <= r < h and 0 <= cc < 7:
                    out[r][cc] = color
            c = start + length - 1 if color == 1 else start
            r += 1

    return out
